-- Add the remaining individual grammar topics listed in Book 3 contents.
begin;

with extra (lesson_number, sort_order, title, summary, explanation, examples, irab) as (
  values
  ('1', 40, 'وَاوُ الْحَالِ (Ва состояния)', 'Связывает действие с одновременным состоянием.', 'وَاوُ الْحَالِ вводит именное или глагольное предложение, описывающее состояние во время основного действия. После неё предложение имеет самостоятельную синтаксическую структуру.', '<li><span dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَهُوَ مُبْتَسِمٌ</span> — студент пришёл, улыбаясь.</li><li><span dir="rtl" lang="ar">خَرَجْتُ وَالشَّمْسُ طَالِعَةٌ</span> — я вышел, когда солнце взошло.</li><li><span dir="rtl" lang="ar">رَأَيْتُهُ وَهُوَ يَقْرَأُ</span> — я увидел его читающим.</li>', '<span dir="rtl" lang="ar">وَهُوَ مُبْتَسِمٌ: الْوَاوُ وَاوُ الْحَالِ، وَهُوَ مُبْتَدَأٌ، مُبْتَسِمٌ خَبَرٌ.</span>'),
  ('1', 41, 'لَعَلَّ (Частица надежды и опасения)', 'Вводит надежду или опасение и управляет именным предложением.', 'لَعَلَّ относится к частицам, уподобленным глаголу: её имя ставится в насбе, а хабар сохраняет раф‘. Перевод определяется контекстом: «возможно», «надеюсь», «вероятно».', '<li><span dir="rtl" lang="ar">لَعَلَّ الطَّالِبَ نَاجِحٌ</span> — возможно, студент успешен.</li><li><span dir="rtl" lang="ar">لَعَلَّ الْمَرِيضَ شَافٍ</span> — надеюсь, больной выздоравливает.</li><li><span dir="rtl" lang="ar">لَعَلَّ الْمَطَرَ نَازِلٌ</span> — возможно, идёт дождь.</li>', '<span dir="rtl" lang="ar">الطَّالِبَ: اسْمُ لَعَلَّ مَنْصُوبٌ، نَاجِحٌ: خَبَرُهَا مَرْفُوعٌ.</span>'),
  ('1', 42, 'اسْمُ الْفِعْلِ (Имя-глагол)', 'Передаёт значение глагола, но оформляется как неизменяемое имя.', 'Имя-глагол выражает действие или побуждение, не принимая обычных признаков глагола. Его значение устанавливается по контексту, а синтаксическая роль зависимых слов определяется как при соответствующем глаголе.', '<li><span dir="rtl" lang="ar">صَهْ عَنِ الْكَلَامِ</span> — замолчи и не говори.</li><li><span dir="rtl" lang="ar">مَهْ عَنِ الْخَطَإِ</span> — перестань ошибаться.</li><li><span dir="rtl" lang="ar">آمِينَ يَا رَبَّ الْعَالَمِينَ</span> — аминь, Господь миров.</li>', '<span dir="rtl" lang="ar">عَنِ الْكَلَامِ: جَارٌّ وَمَجْرُورٌ مُتَعَلِّقٌ بِمَعْنَى اسْمِ الْفِعْلِ.</span>'),
  ('1', 43, 'مِنَ الزَّائِدَةُ (Дополнительная «мин»)', 'Подчёркивает полное отрицание и влияет на падеж после себя.', 'Мِنْ الزَّائِدَةُ появляется после отрицания или вопроса перед неопределённым именем. Формально она не добавляет самостоятельного обстоятельственного значения, а усиливает охват отрицания; имя после неё обычно бывает в джарре.', '<li><span dir="rtl" lang="ar">مَا جَاءَنِي مِنْ أَحَدٍ</span> — ко мне никто не приходил.</li><li><span dir="rtl" lang="ar">هَلْ مِنْ طَالِبٍ فِي الْفَصْلِ؟</span> — есть ли в классе хоть один студент?</li><li><span dir="rtl" lang="ar">مَا عِنْدِي مِنْ كِتَابٍ</span> — у меня нет ни одной книги.</li>', '<span dir="rtl" lang="ar">أَحَدٍ: اسْمٌ مَجْرُورٌ لَفْظًا بِمِنْ الزَّائِدَةِ وَمَرْفُوعٌ مَحَلًّا فَاعِلٌ.</span>'),
  ('1', 44, 'لَدَى (Наречие «у, при»)', 'Именное наречие места и обладания, часто входящее в идафу.', 'لَدَى относится к обстоятельственным именам и обычно присоединяет к себе имя или местоимение. При идафе следующий член является маджруром, а местоимение после لَدَى занимает позицию мудоф иляйхи.', '<li><span dir="rtl" lang="ar">لَدَيَّ كِتَابٌ</span> — у меня есть книга.</li><li><span dir="rtl" lang="ar">لَدَى الطَّالِبِ قَلَمٌ</span> — у студента есть ручка.</li><li><span dir="rtl" lang="ar">بَقِيتُ لَدَيْهِ</span> — я остался у него.</li>', '<span dir="rtl" lang="ar">لَدَيَّ: ظَرْفٌ مَرْفُوعٌ مَحَلًّا خَبَرٌ مُقَدَّمٌ، كِتَابٌ مُبْتَدَأٌ مُؤَخَّرٌ.</span>'),
  ('1', 45, 'مَنْعُ أَشْيَاءَ مِنَ الصَّرْفِ (Причина несклоняемости أشياء)', 'Некоторые формы не принимают танвин и имеют фатху в джарре.', 'Слово أَشْيَاءُ относится к именам, запрещённым к склонению, из-за своей морфологической модели. Поэтому без ال и без идафы оно не принимает танвин, а в родительном падеже получает фатху.', '<li><span dir="rtl" lang="ar">هَذِهِ أَشْيَاءُ مُفِيدَةٌ</span> — это полезные вещи.</li><li><span dir="rtl" lang="ar">رَأَيْتُ أَشْيَاءَ جَدِيدَةً</span> — я увидел новые вещи.</li><li><span dir="rtl" lang="ar">بَحَثْتُ عَنْ أَشْيَاءَ مُهِمَّةٍ</span> — я искал важные вещи.</li>', '<span dir="rtl" lang="ar">أَشْيَاءَ: اسْمٌ مَجْرُورٌ بِعَنْ وَعَلَامَةُ جَرِّهِ الْفَتْحَةُ نِيَابَةً عَنِ الْكَسْرَةِ.</span>'),
  ('2', 46, 'الْمَاضِي لِلدُّعَاءِ وَنَفْيُهُ (Прошедшее время для мольбы и его отрицание)', 'Прошедшая форма может выражать просьбу о будущем результате.', 'Форма прошедшего времени в دعا́ может использоваться для закреплённой надежды или мольбы. При отрицании выбор частицы зависит от смысла: مَا обычно отрицает факт, а لَمْ связывает отрицание с настоящим результатом.', '<li><span dir="rtl" lang="ar">رَحِمَكَ اللَّهُ</span> — да помилует тебя Аллах.</li><li><span dir="rtl" lang="ar">غَفَرَ اللَّهُ لَهُ</span> — да простит его Аллах.</li><li><span dir="rtl" lang="ar">لَمْ يَحْضُرْ الطَّالِبُ</span> — студент не пришёл.</li>', '<span dir="rtl" lang="ar">رَحِمَكَ: فِعْلٌ مَاضٍ لَفْظًا، وَالْمَعْنَى دُعَاءٌ، وَالْكَافُ مَفْعُولٌ بِهِ.</span>'),
  ('2', 47, 'النِّدَاءُ بِالِاسْمِ الْمُحَلَّى بِأَلْ (Обращение к имени с ال)', 'Перед определённым именем в обращении используется специальная конструкция.', 'Имя с ال обычно не вызывается непосредственно частицей يَا. В нормативной речи перед ним употребляют أَيُّهَا или أَيَّتُهَا с последующим определением, согласованным с родом.', '<li><span dir="rtl" lang="ar">يَا أَيُّهَا الطَّالِبُ</span> — о студент!</li><li><span dir="rtl" lang="ar">يَا أَيَّتُهَا الْمُؤْمِنَةُ</span> — о верующая!</li><li><span dir="rtl" lang="ar">يَا أَيُّهَا الْمُدَرِّسُونَ</span> — о преподаватели!</li>', '<span dir="rtl" lang="ar">أَيُّهَا: مُنَادًى مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ نَصْبٍ.</span>'),
  ('2', 48, 'أَسْمَاءُ الشُّهُورِ (Названия месяцев)', 'Названия месяцев употребляются как имена с нормативной огласовкой.', 'Названия месяцев являются именами собственными и обычно определены самим значением. В идафе или после предлога их падеж определяется синтаксической позицией, а не переводом.', '<li><span dir="rtl" lang="ar">جَاءَ شَهْرُ رَمَضَانَ</span> — пришёл месяц Рамадан.</li><li><span dir="rtl" lang="ar">صُمْتُ فِي رَمَضَانَ</span> — я постился в Рамадан.</li><li><span dir="rtl" lang="ar">بَعْدَ شَوَّالٍ نَعُودُ</span> — после Шавваля мы возвращаемся.</li>', '<span dir="rtl" lang="ar">رَمَضَانَ: مُضَافٌ إِلَيْهِ مَجْرُورٌ بِالْفَتْحَةِ لِمَنْعِهِ مِنَ الصَّرْفِ.</span>'),
  ('2', 49, 'إِمَّا (Разделительная частица «либо… либо»)', 'Соединяет равноправные варианты выбора.', 'إِمَّا обычно повторяется перед каждым вариантом и вводит распределение или альтернативу. Вторая часть конструкции сохраняет свою синтаксическую роль, а إِمَّا не меняет окончания слов.', '<li><span dir="rtl" lang="ar">إِمَّا أَنْ تَدْرُسَ وَإِمَّا أَنْ تَعْمَلَ</span> — либо учись, либо работай.</li><li><span dir="rtl" lang="ar">سَأَذْهَبُ إِمَّا الْيَوْمَ وَإِمَّا غَدًا</span> — я пойду либо сегодня, либо завтра.</li><li><span dir="rtl" lang="ar">إِمَّا صِدْقًا وَإِمَّا صَمْتًا</span> — либо правду, либо молчание.</li>', '<span dir="rtl" lang="ar">أَنْ تَدْرُسَ: مَصْدَرٌ مُؤَوَّلٌ، وَإِمَّا حَرْفُ تَخْيِيرٍ لَا مَحَلَّ لَهُ.</span>'),
  ('2', 50, 'اسْمُ الْجِنْسِ الْجَمْعِيُّ (Собирательное имя)', 'Единственная форма обозначает совокупность однородных предметов.', 'Собирательное имя обозначает вид или множество в форме единственного числа. Для обозначения одной единицы часто прибавляется ة, а грамматический род определяется формой конкретного слова.', '<li><span dir="rtl" lang="ar">حَضَرَ الْيَهُودُ</span> — явились иудеи.</li><li><span dir="rtl" lang="ar">رَأَيْتُ يَهُودِيًّا</span> — я увидел одного иудея.</li><li><span dir="rtl" lang="ar">فِي الْبُسْتَانِ شَجَرٌ</span> — в саду есть деревья.</li>', '<span dir="rtl" lang="ar">يَهُودِيًّا: اسْمٌ مَفْرَدٌ مَنْصُوبٌ بِالْفَتْحَةِ، وَهُوَ وَاحِدُ الْجِنْسِ.</span>'),
  ('2', 51, 'إِعْرَابُ ثَلَاثَةٍ وَأَخَوَاتِهَا (Согласование числительных 3–10)', 'Числительное и существительное после него имеют особое согласование.', 'Числительные от трёх до десяти противопоставлены существительному по роду. Существительное после них ставится во множественном числе и в родительном падеже, а числительное согласуется с падежом конструкции.', '<li><span dir="rtl" lang="ar">ثَلَاثَةُ طُلَّابٍ</span> — три студента.</li><li><span dir="rtl" lang="ar">قَرَأْتُ ثَلَاثَةَ كُتُبٍ</span> — я прочитал три книги.</li><li><span dir="rtl" lang="ar">مَرَرْتُ بِثَلَاثَةِ طُلَّابٍ</span> — я прошёл мимо трёх студентов.</li>', '<span dir="rtl" lang="ar">طُلَّابٍ: تَمْيِيزٌ مَجْرُورٌ بِالْكَسْرَةِ، وَثَلَاثَةُ مُضَافٌ.</span>'),
  ('9', 52, 'ذَانِكَ وَتَانِكَ (Указательные слова для двойственного числа)', 'Двойственные указательные слова согласуются с родом и падежом.', 'Формы ذَانِكَ и تَانِكَ указывают на два удалённых предмета мужского и женского рода. При изменении падежа конечный алиф превращается в ياء: ذَيْنِكَ и تَيْنِكَ.', '<li><span dir="rtl" lang="ar">ذَانِكَ طَالِبَانِ</span> — те двое студентов.</li><li><span dir="rtl" lang="ar">رَأَيْتُ ذَيْنِكَ الطَّالِبَيْنِ</span> — я увидел тех двух студентов.</li><li><span dir="rtl" lang="ar">تَانِكَ مُعَلِّمَتَانِ</span> — те две учительницы.</li>', '<span dir="rtl" lang="ar">ذَيْنِكَ: اسْمُ إِشَارَةٍ مَبْنِيٌّ فِي مَحَلِّ نَصْبٍ مَفْعُولٍ بِهِ.</span>'),
  ('9', 53, 'صِيغَةُ الْأَمْرِ مِنْ أَتَى (Повелительная форма от أتى)', 'Повелительная форма строится от настоящего времени после удаления приставки.', 'При образовании повелительного наклонения от глагола أَتَى учитываются начальная хамза, слабая последняя буква и лицо адресата. Нормативная форма أْتِ для единственного мужского рода имеет конечную касру.', '<li><span dir="rtl" lang="ar">أْتِ إِلَيَّ</span> — подойди ко мне.</li><li><span dir="rtl" lang="ar">أْتِيَا مُبَكِّرَيْنِ</span> — приходите вдвоём рано.</li><li><span dir="rtl" lang="ar">أْتُوا بِالْكِتَابِ</span> — принесите книгу.</li>', '<span dir="rtl" lang="ar">أْتِ: فِعْلُ أَمْرٍ مَبْنِيٌّ عَلَى حَذْفِ حَرْفِ الْعِلَّةِ.</span>'),
  ('15', 54, 'بَقِيَّةُ مَوَاضِعِ اقْتِرَانِ الْجَوَابِ بِالْفَاءِ (Остальные случаи фа условия)', 'Фа обязательна перед ответом, имеющим форму, несовместимую с прямым джазмом.', 'Ответ условию соединяется с фа, если он именной, начинается с قد или لن, содержит لَنْ, مَا, لَا, либо выражает приказ или вопрос. Это структурный показатель границы между условием и его следствием.', '<li><span dir="rtl" lang="ar">إِنْ تَجْتَهِدْ فَأَنْتَ نَاجِحٌ</span> — если стараешься, ты успешен.</li><li><span dir="rtl" lang="ar">مَنْ يَصْدُقْ فَقَدْ نَجَا</span> — кто правдив, тот спасся.</li><li><span dir="rtl" lang="ar">إِنْ تَسْأَلْ فَلَا تَخَفْ</span> — если спросишь, не бойся.</li>', '<span dir="rtl" lang="ar">فَأَنْتَ نَاجِحٌ: جَوَابُ الشَّرْطِ مُقْتَرِنٌ بِالْفَاءِ لِأَنَّهُ جُمْلَةٌ اسْمِيَّةٌ.</span>'),
  ('15', 55, 'تَصْغِيرُ كِتَابٍ (Уменьшительная форма)', 'Уменьшение передаёт малый размер или оттенок ласкательности.', 'Трёхбуквенные имена обычно переводятся на модель فُعَيْلٍ. Уменьшительная форма не заменяет обычное множественное число и должна сохранять корневые согласные.', '<li><span dir="rtl" lang="ar">كِتَابٌ صُغَيْرٌ</span> — маленькая книга.</li><li><span dir="rtl" lang="ar">هَذَا كُتَيِّبٌ نَافِعٌ</span> — это полезная книжечка.</li><li><span dir="rtl" lang="ar">قَرَأْتُ كُتَيِّبًا</span> — я прочитал небольшую книжку.</li>', '<span dir="rtl" lang="ar">كُتَيِّبٌ: خَبَرٌ مَرْفُوعٌ، وَهُوَ مُصَغَّرٌ عَلَى وَزْنِ فُعَيِّلٍ.</span>'),
  ('16', 56, 'بَابُ تَفَعَّلَ (V порода)', 'Пятая порода образуется с تَ и удвоением второй корневой буквы.', 'Модель تَفَعَّلَ часто обозначает действие субъекта над собой, постепенное приобретение качества или проявление результата формы II. Перевод не выводится механически и проверяется по контексту.', '<li><span dir="rtl" lang="ar">تَعَلَّمَ الطَّالِبُ</span> — студент учился.</li><li><span dir="rtl" lang="ar">تَكَسَّرَ الزُّجَاجُ</span> — стекло разбилось.</li><li><span dir="rtl" lang="ar">تَذَكَّرْتُ الدَّرْسَ</span> — я вспомнил урок.</li>', '<span dir="rtl" lang="ar">تَعَلَّمَ: فِعْلٌ مَاضٍ عَلَى وَزْنِ تَفَعَّلَ، وَالطَّالِبُ فَاعِلٌ.</span>'),
  ('16', 57, 'مَصْدَرُ فَعُلَ وَفِعَالٌ (Модели масдара)', 'Некоторые масдары трёхбуквенного глагола имеют модели فَعَالٌ и другие.', 'Масдары простого трёхбуквенного глагола преимущественно слышимые, а не полностью выводимые по одной формуле. Модель помогает классифицировать слово, но нормативную форму следует подтверждать словарём.', '<li><span dir="rtl" lang="ar">كَرُمَ كَرَمًا</span> — быть щедрым; щедрость.</li><li><span dir="rtl" lang="ar">قَاتَلَ قِتَالًا</span> — сражаться; сражение.</li><li><span dir="rtl" lang="ar">جَاهَدَ جِهَادًا</span> — усердствовать; усердие.</li>', '<span dir="rtl" lang="ar">كَرَمًا: مَفْعُولٌ مُطْلَقٌ مَنْصُوبٌ، وَهُوَ مَصْدَرٌ.</span>'),
  ('17', 58, 'لَامُ الِابْتِدَاءِ (Лям начала)', 'Усиливает утверждение и обычно входит в именную конструкцию.', 'Лям начала присоединяется к мубтада или хабару после частиц, которые допускают её смещение, и служит для смыслового выделения. Она не меняет падеж слова.', '<li><span dir="rtl" lang="ar">لَأَنْتَ صَادِقٌ</span> — поистине, ты правдив.</li><li><span dir="rtl" lang="ar">إِنَّ الطَّالِبَ لَمُجْتَهِدٌ</span> — поистине, студент прилежен.</li><li><span dir="rtl" lang="ar">وَاللَّهِ لَأَفْعَلَنَّ</span> — клянусь Аллахом, я непременно сделаю.</li>', '<span dir="rtl" lang="ar">لَمُجْتَهِدٌ: لَامُ الِابْتِدَاءِ لَا مَحَلَّ لَهَا، وَمُجْتَهِدٌ خَبَرٌ مَرْفُوعٌ.</span>'),
  ('17', 59, 'أَصْبَحَ وَأَمْسَى (Глаголы времени из группы كان)', 'Глаголы ناقصة переводят именное предложение в конструкцию с временным оттенком.', 'أَصْبَحَ и أَمْسَى входят в группу كان وأخواتها: их имя остаётся в раф‘, а хабар становится в насбе. Они добавляют значение состояния утром или вечером, а не просто обозначают время.', '<li><span dir="rtl" lang="ar">أَصْبَحَ الطَّالِبُ نَشِيطًا</span> — студент стал активным утром.</li><li><span dir="rtl" lang="ar">أَمْسَى الْجَوُّ بَارِدًا</span> — к вечеру погода стала холодной.</li><li><span dir="rtl" lang="ar">أَصْبَحَ الْعِلْمُ مُهِمًّا</span> — знание стало важным.</li>', '<span dir="rtl" lang="ar">الطَّالِبُ: اسْمُ أَصْبَحَ مَرْفُوعٌ، نَشِيطًا: خَبَرُهَا مَنْصُوبٌ.</span>'),
  ('17', 60, 'أَوْشَكَ (Глагол приближения)', 'Описывает близость наступления действия.', 'أَوْشَكَ относится к глаголам приближения и действует подобно ناقص: имя стоит в раф‘, а сообщение часто выражается предложением с أَنْ и настоящим временем.', '<li><span dir="rtl" lang="ar">أَوْشَكَ الدَّرْسُ أَنْ يَنْتَهِيَ</span> — урок почти закончился.</li><li><span dir="rtl" lang="ar">أَوْشَكَ الْمَطَرُ أَنْ يَنْزِلَ</span> — дождь вот-вот пойдёт.</li><li><span dir="rtl" lang="ar">أَوْشَكَ الطَّالِبُ أَنْ يَنْجَحَ</span> — студент почти добился успеха.</li>', '<span dir="rtl" lang="ar">الدَّرْسُ: اسْمُ أَوْشَكَ مَرْفُوعٌ، أَنْ يَنْتَهِيَ: خَبَرٌ فِي مَحَلِّ نَصْبٍ.</span>'),
  ('17', 61, 'لَوْلَا (Условная частица предотвращённого условия)', 'Выражает, что действие не произошло из-за существования другого обстоятельства.', 'لَوْلَا обычно входит в конструкцию «если бы не…». После неё следует имя, которое грамматически является мубтада, а хабар часто опущен и понятен из контекста.', '<li><span dir="rtl" lang="ar">لَوْلَا اللَّهُ لَهَلَكْنَا</span> — если бы не Аллах, мы погибли бы.</li><li><span dir="rtl" lang="ar">لَوْلَا الْعِلْمُ لَضَلَّ النَّاسُ</span> — если бы не знание, люди заблудились бы.</li><li><span dir="rtl" lang="ar">لَوْلَا الْمَطَرُ لَخَرَجْنَا</span> — если бы не дождь, мы вышли бы.</li>', '<span dir="rtl" lang="ar">اللَّهُ: مُبْتَدَأٌ مَرْفُوعٌ، وَخَبَرُهُ مَحْذُوفٌ تَقْدِيرُهُ مَوْجُودٌ.</span>'),
  ('17', 62, 'حَذْفُ هَمْزَةِ ابْنٍ (Удаление хамзы в ابن)', 'Хамза ابن пишется без начальной огласовки в определённых позициях.', 'Начальная хамза ابن является хамзат аль-васл. В письменной форме она опускается между двумя собственными именами, если ابن не начинает строку и не является первым членом самостоятельной конструкции.', '<li><span dir="rtl" lang="ar">مُحَمَّدُ بْنُ عَبْدِ اللَّهِ</span> — Мухаммад ибн Абдуллах.</li><li><span dir="rtl" lang="ar">هَذَا ابْنُ خَالِدٍ</span> — это сын Халида.</li><li><span dir="rtl" lang="ar">جَاءَ ابْنُ الْمُدَرِّسِ</span> — пришёл сын преподавателя.</li>', '<span dir="rtl" lang="ar">بْنُ: نَعْتٌ أَوْ بَدَلٌ مَرْفُوعٌ، وَحُذِفَتْ هَمْزَتُهُ لِوُقُوعِهِ بَيْنَ عَلَمَيْنِ.</span>'),
  ('17', 63, 'مَا النَّكِرَةُ التَّامَّةُ الْمُبْهَمَةُ (Неопределённая полная «ма»)', 'Ма может быть самостоятельным неопределённым именем со значением «что-либо».', 'В отличие от отрицательной или вопросительной частицы, مَا النَّكِرَةُ التَّامَّةُ занимает именную позицию и получает падеж по роли в предложении. Её значение уточняется последующим описанием или контекстом.', '<li><span dir="rtl" lang="ar">أَعْطِنِي مَا أُرِيدُ</span> — дай мне то, что я хочу.</li><li><span dir="rtl" lang="ar">رَأَيْتُ مَا يَسُرُّنِي</span> — я увидел то, что меня радует.</li><li><span dir="rtl" lang="ar">خُذْ مَا تَجِدُ</span> — возьми то, что найдёшь.</li>', '<span dir="rtl" lang="ar">مَا: اسْمٌ مَوْصُولٌ أَوْ نَكِرَةٌ تَامَّةٌ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.</span>')
)
insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary)
select 'Мединский курс (Том 3)', lesson_number, title,
  '<p><strong>Академическое объяснение.</strong> ' || explanation || '</p><p><strong>Три примера.</strong></p><ol>' || examples || '</ol><p><strong>Полный разбор إِعْرَاب.</strong><br>' || irab || '</p>',
  sort_order, 'rule', summary
from extra;
commit;
